from pathlib import Path
p = Path('presentation/2026-06-15/grpc-tonic-stack/deck.typ')
text = p.read_text()
# Lightweight delimiter balance, ignoring comments/strings is intentionally not attempted;
# output is a guardrail for accidental unbalanced structural edits.
stack=[]
pairs={')':'(',']':'[','}':'{'}
opens=set(pairs.values())
line=col=1
errors=[]
for ch in text:
    if ch in opens:
        stack.append((ch,line,col))
    elif ch in pairs:
        if not stack or stack[-1][0] != pairs[ch]:
            errors.append((line,col,ch,stack[-1] if stack else None))
            break
        stack.pop()
    if ch == '\n':
        line += 1; col = 1
    else:
        col += 1
print(f"deck.typ delimiter errors: {len(errors)}")
print(f"deck.typ remaining opener count: {len(stack)}")
if errors:
    print(errors[0])
# Also check helper-related calls still have expected counts.
for needle in ['#detail-sequence(', '#detail-caveat(', '#detail-state(', '#detail-diagram-frame[']:
    print(f"{needle} {text.count(needle)}")
PY

